package com.railflow.yardops.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="scan_events") public class ScanEvent { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; private String carNumber; private String yardCode; private String eventType; private Instant occurredAt; protected ScanEvent(){} public ScanEvent(String carNumber,String yardCode,String eventType,Instant occurredAt){this.carNumber=carNumber;this.yardCode=yardCode;this.eventType=eventType;this.occurredAt=occurredAt;} public UUID getId(){return id;} public String getCarNumber(){return carNumber;} public String getYardCode(){return yardCode;} public String getEventType(){return eventType;} public Instant getOccurredAt(){return occurredAt;} }